from __future__ import annotations

import json
import sys

from omni_prod import discovery as d

PROMPT = 'אתר לחנות פרחים עם משלוחים לאילת ותשלום במזומן בלבד'


def brief():
    b = d.start(PROMPT, mode=d.RECOMMEND)
    return d.answer(b, {'login': 'none', 'personal_data': 'no', 'content_only': 'no'})


def view(lang='he'):
    """Same shape as investor_app._discovery_view for revision 1."""
    b = brief()
    answered = [{**q.to_dict(lang), 'value': b.fields[q.field]['value'],
                 'value_label': d._label(q, b.fields[q.field]['value'], lang), 'source': b.fields[q.field]['source']}
                for q in d.QUESTIONS if q.field in b.fields]
    return {'brief': {'revision': 1, 'fingerprint': b.fingerprint()}, 'prompt': b.prompt, 'mode': b.mode,
            'group': None, 'group_title': None, 'questions': [], 'answered': answered, 'complete': d.complete(b),
            'progress': {'answered': len(answered), 'remaining': len(d.pending(b))}, 'summary': d.summary(b, lang)}


def plan():
    return {'can_build': True, 'brief_revision': 1, 'build_contract_id': 'bc_fixture', 'capabilities': [],
            'infrastructure': [], 'product': {'summary': PROMPT}, 'blockers': [], 'clarification_questions': [],
            'credits_required': 1, 'allowance': {'credits_remaining': 9}, 'build_authorization': 'PRICED'}


def fixture():
    return {'view': view(), 'plan': plan()}


if __name__ == '__main__':
    json.dump(fixture(), sys.stdout, ensure_ascii=False, indent=1, sort_keys=True)
    sys.stdout.write('\n')
